from research_helpers import *
a=ev('https://www.codaoctopus.com/products/3d/sonars/echoscope-sonar-gallery','Public manufacturer sonar configurator data directly read and reviewed: exact displayed title, dual/triple frequency configuration, depth rating and supported vehicle platform. Website catalogue IDs are not manufacturer model numbers.')
b=ev('https://www.codaoctopus.com/commercial/sectors/marine-robotics','Manufacturer directly describes sonars for ROV/AUV navigation, obstacle avoidance and inspection in poor visibility, establishing robotics component relevance.')
c=ev('https://www.codaoctopusgroup.com/','Parent issuer confirms Coda Octopus Products wholly owned; parent recorded as commercial partner rather than direct hardware manufacturer.')
ps=[]
for r in json.loads((out/'coda-public-sonars.json').read_text()):
 title=r['title'].strip().replace('®','')
 if 'WAVM' in title or 'CIVS DUO' in title or 'Handheld' in title:continue
 source=ev('https://www.codaoctopus.com'+r['url'],'Exact sonar configuration listed in current public manufacturer configurator; depth/frequency labels retained as descriptive configuration names, not invented part numbers.')
 name=title+' '+r['subtitle']+' '+r['depthRating'].replace('Up to ','')
 attrs={'manufacturer_family':title,'frequency_configuration':r['subtitle'],'manufacturer_depth_rating':r['depthRating'],'supported_platforms':r['platform'],'manufacturer_catalogue_entry_id':r['id'],'identity_scope':'manufacturer-listed configuration; descriptive name, no verified part number','robotics_use':'ROV/AUV/USV sonar perception, navigation or inspection'}
 ps.append(p(name,'Real-time volumetric imaging sonar configuration for underwater vehicle perception, navigation or inspection.',source,'commercial',roles=['commercial_partner'],typ='product',sector='robotics',sub='autonomy_and_components',attributes=attrs,evidence=[source,a,b,c]))
d=ev('https://www.codaoctopus.com/products/3d/sonars/echoscope-wavm','WAVM is wide-area volumetric mapping technology available on full-size PIPE and C500 sonars. Depth configurations not duplicated as separate software modules.')
e=ev('https://www.codaoctopus.com/products/3d/sonars/echoscope-pipe-civs-duo','CIVS DUO explicitly described as integrated technology block, not standalone sonar; close-in inspection and underwater vehicle deployments.')
f=ev('https://www.codaoctopus.com/products/3d/echoscope-pipe-nano-gen-series-sonars/echoscope-pipe-nano-gen-series','Current NANO Gen family directly designed for underwater vehicles/robotic platforms; depth options250/600/3000m, individual exact model mapping not established. Conflicting frequency/FOV text not normalized into unverified model specs.')
for name,desc,source,typ,attrs in [('Echoscope PIPE WAVM','Wide-area volumetric mapping technology module for full-size PIPE and C500 sonars.',d,'technology',{'maximum_across_track_swath_degrees':125}),('Echoscope PIPE CIVS DUO','Integrated close-in visualization and medium-frequency volumetric sonar technology block for underwater vehicle inspection.',e,'technology',{'standalone_sonar':False,'medium_frequency_khz':375}),('Echoscope PIPE NANO Gen Series','Compact real-time volumetric sonar family for underwater robotic perception and navigation; exact per-model mapping unverified.',f,'product',{'identity_scope':'manufacturer product family','depth_rating_options_m':[250,600,3000]})]:ps.append(p(name,desc,source,'commercial',roles=['commercial_partner'],typ=typ,sector='robotics',sub='autonomy_and_components',attributes=attrs,evidence=[source,b,c]))
cs=[company('Coda Octopus Group Inc',ps,[a,b,c,d,e,f],'60 exact displayed dual/triple-frequency and depth sonar configurations reviewed, plus NANO Gen family and WAVM/CIVS technology modules. Parent relationship established; internal catalogue IDs not represented as part numbers. Handheld-only configurations, integrated rotators, motion/navigation units, robot inspection kits, software modules and other acquired subsidiaries require further research. WAVM depth listings grouped as one shared module, CIVS explicitly not standalone sonar; no automatic inclusion of diver-only equipment.')]
(out/'batch-0119.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
